rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function d0() { return true; }
    function d1() { return d0() && d0(); }
    function d2() { return d1() && d1(); }
    function d3() { return d2() && d2(); }
    function d4() { return d3() && d3(); }
    function d5() { return d4() && d4(); }
    function d6() { return d5() && d5(); }
    function d7() { return d6() && d6(); }
    function f(a) { return a; }
    function g(a) { return debug(a); }
    function h() { let x = debug(7); return true; }
    function k(a, b) { return true; }
    function m() { let x = 1; let y = debug(7); return true; }
    match /c/{id} {
      allow get: if d7() && d6() && d2() && d1() && d0() && d0() && true && d1() && debug(7) == 7;
    }
  }
}

